import java.util.Scanner;

public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long w = sc.nextInt();
        long m = sc.nextInt();
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        if (m < 0) {
            System.out.println("NO");
            return;
        }
        int n = 0;
        long[] bases = new long[100];
        for (long v = 1; v <= 2_000_000_000L; v *= w) {
            bases[n++] = v;
        }

        int[] digits = new int[n];
        long curTotal = 0;
        for (int i = 0; i < n; i++) curTotal -= bases[i];

        boolean works = false;
        outer:
        while (true) {
            int index = 0;
            while (true) {
                digits[index]++;
                curTotal += bases[index];
                if (digits[index] != 3) {
                    if (Math.abs(curTotal) == m) {
                        works = true;
                    }
                    break;
                }
                digits[index] = 0;
                curTotal -= bases[index] * 3;
                index++;
                if (index == n) break outer;
            }
        }
        System.out.println(works ? "YES" : "NO");
    }
}
